def nearest_center(g, metric='manhattan'):
 a=np.array(g);H,W=a.shape;o=a.copy();seeds=[(r,c,int(a[r,c])) for r in range(H) for c in range(W) if a[r,c]>1]
 for r in range(1,H-1):
  for c in range(1,W-1):
   if all(a[x,y] in (1, a[r,c]) for x in range(r-1,r+2) for y in range(c-1,c+2)) and all(a[x,y]!=0 for x in range(r-1,r+2) for y in range(c-1,c+2)):
    def dist(s):
     dr,dc=abs(r-s[0]),abs(c-s[1]);return dr+dc if metric=='manhattan' else max(dr,dc) if metric=='cheb' else dr*dr+dc*dc
    o[r,c]=min(seeds,key=dist)[2]
 return o
